extends SceneTree
var vp: SubViewport

func _solid(c: Color, w := 40, h := 40) -> ImageTexture:
	var img := Image.create(w, h, false, Image.FORMAT_RGBA8)
	img.fill(c)
	return ImageTexture.create_from_image(img)
func _spr(parent: Node, c: Color, pos: Vector2, w := 40, h := 40) -> Sprite2D:
	var s := Sprite2D.new(); s.texture = _solid(c, w, h); s.centered = false; s.position = pos
	parent.add_child(s); return s
func _clear() -> void:
	for c in vp.get_children(): c.free()
	await process_frame
func _px(x: int, y: int) -> String:
	var c := vp.get_texture().get_image().get_pixel(x, y)
	for p in [[Color.RED,"RED"],[Color.GREEN,"GREEN"],[Color.BLUE,"BLUE"],[Color.YELLOW,"YELLOW"],[Color.BLACK,"BLACK"]]:
		if c.is_equal_approx(p[0]): return p[1]
	return str(c)
func _f() -> void:
	await process_frame; await process_frame

# one 48x48 atlas, tile 0 = wall face (blue, 48x72 drawn up? keep 48x48 here), with y_sort_origin
func _tileset(origin: int) -> TileSet:
	var ts := TileSet.new(); ts.tile_size = Vector2i(48, 48)
	var src := TileSetAtlasSource.new()
	var img := Image.create(48, 48, false, Image.FORMAT_RGBA8); img.fill(Color.BLUE)
	src.texture = ImageTexture.create_from_image(img)
	src.texture_region_size = Vector2i(48, 48)
	src.create_tile(Vector2i(0, 0))
	ts.add_source(src, 0)
	src.get_tile_data(Vector2i(0, 0), 0).y_sort_origin = origin
	return ts

func _initialize() -> void:
	vp = SubViewport.new(); vp.size = Vector2i(400, 300); vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	root.add_child(vp)
	_run()

func _run() -> void:
	# T1: ysort TileMapLayer (cell (0,1) => y 48..96, origin 24 => key 72) vs sibling sprite keys 60 / 80, all under ysort parent
	for key_spr in [60, 80]:
		await _clear()
		var par := Node2D.new(); par.y_sort_enabled = true; vp.add_child(par)
		var tml := TileMapLayer.new(); tml.tile_set = _tileset(24); tml.y_sort_enabled = true
		par.add_child(tml)
		tml.set_cell(Vector2i(0, 1), 0, Vector2i(0, 0))   # screen y 48..96, x 0..48
		_spr(par, Color.RED, Vector2(20, key_spr - 40), 40, 40) # sprite keyed by position.y => key_spr-40... set position so key = key_spr
		par.get_child(1).position = Vector2(20, key_spr)
		par.get_child(1).offset = Vector2(0, -40)       # draw 40 above the key line (feet on the key)
		await _f()
		print("T1 sprite key ", key_spr, " vs tile key 72 (cell y 48 + origin 24): overlap pixel (30,70) = ", _px(30, 70), "  (RED => sprite over tile)")
	# T2: tile layer NOT y-sort enabled, parent ysort, sibling sprite keyed 60 & 80: tml node key = its position.y 0
	for key_spr in [60, 80]:
		await _clear()
		var par := Node2D.new(); par.y_sort_enabled = true; vp.add_child(par)
		var tml := TileMapLayer.new(); tml.tile_set = _tileset(24); tml.y_sort_enabled = false
		par.add_child(tml)
		tml.set_cell(Vector2i(0, 1), 0, Vector2i(0, 0))
		var s := _spr(par, Color.RED, Vector2(20, key_spr), 40, 40); s.offset = Vector2(0, -40)
		await _f()
		print("T2 non-ysort tile layer (key = node y 0) vs sprite key ", key_spr, ": (30,70) = ", _px(30, 70), " (RED => sprite over tile)")
	# T3: ysort tile layer positioned at a section offset (0,100) inside ysort parent; cell (0,0) origin 24 -> key 124 ; sprite key 110/130
	for key_spr in [110, 130]:
		await _clear()
		var par := Node2D.new(); par.y_sort_enabled = true; vp.add_child(par)
		var tml := TileMapLayer.new(); tml.tile_set = _tileset(24); tml.y_sort_enabled = true; tml.position = Vector2(0, 100)
		par.add_child(tml)
		tml.set_cell(Vector2i(0, 0), 0, Vector2i(0, 0))   # global y 100..148, key 100+0+24 = 124
		var s := _spr(par, Color.RED, Vector2(20, key_spr), 40, 40); s.offset = Vector2(0, -40)   # covers y key-40..key
		await _f()
		var py := 118 if key_spr == 110 else 118
		print("T3 offset ysort tile layer (key 124) vs sprite key ", key_spr, ": (30,", py, ") = ", _px(30, py), " (expect sprite 110 => tile on top BLUE ; sprite 130 => RED)")
	# T4: tile layer ysort inside body root (ysort) inside world ysort ; other body's sprite with offsets
	await _clear()
	var world := Node2D.new(); world.y_sort_enabled = true; vp.add_child(world)
	var b1 := Node2D.new(); b1.y_sort_enabled = true; b1.position = Vector2(0, 100); world.add_child(b1)
	var b2 := Node2D.new(); b2.y_sort_enabled = true; world.add_child(b2)
	var tml := TileMapLayer.new(); tml.tile_set = _tileset(24); tml.y_sort_enabled = true
	b1.add_child(tml); tml.set_cell(Vector2i(0, 0), 0, Vector2i(0, 0))   # global key 124
	var s := _spr(b2, Color.RED, Vector2(20, 130), 40, 40); s.offset = Vector2(0, -40)  # key 130 in other body
	await _f()
	print("T4 cross-body: tile (body1 offset) key 124 vs sprite (body2) key 130 at (30,118): ", _px(30, 118), " (RED => merged global sort across bodies)")
	quit()
EOF
