extends SceneTree
var vp: SubViewport
func _f(n := 3) -> void:
	for i in n: await process_frame
func _tileset(sources := 1) -> TileSet:
	var ts := TileSet.new(); ts.tile_size = Vector2i(48, 48)
	for i in sources:
		var src := TileSetAtlasSource.new()
		var img := Image.create(48, 48, false, Image.FORMAT_RGBA8); img.fill(Color.BLUE)
		src.texture = ImageTexture.create_from_image(img); src.texture_region_size = Vector2i(48, 48)
		src.create_tile(Vector2i(0, 0)); ts.add_source(src, i)
	return ts
func _calls() -> int:
	return vp.get_render_info(Viewport.RENDER_INFO_TYPE_CANVAS, Viewport.RENDER_INFO_DRAW_CALLS_IN_FRAME)
func _fill(tml: TileMapLayer, n: int, w: int, ox := 0, oy := 0) -> void:
	for i in n:
		tml.set_cell(Vector2i(ox + i % w, oy + i / w), 0, Vector2i(0, 0))
func _initialize() -> void:
	vp = SubViewport.new(); vp.size = Vector2i(1280, 1280); vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	root.add_child(vp); _run()
func _run() -> void:
	var ts := _tileset()
	# A: one TileMapLayer, 453 cells, no ysort
	var a := TileMapLayer.new(); a.tile_set = ts; vp.add_child(a)
	var t0 := Time.get_ticks_usec(); _fill(a, 453, 20); var t1 := Time.get_ticks_usec()
	await _f(); print("A one layer 453 cells no-ysort: set_cell total us ", t1 - t0, " draw calls ", _calls(), " quadrant ", a.rendering_quadrant_size)
	a.free(); await _f()
	# B: same ysort
	var par := Node2D.new(); par.y_sort_enabled = true; vp.add_child(par)
	var b := TileMapLayer.new(); b.tile_set = ts; b.y_sort_enabled = true; par.add_child(b)
	t0 = Time.get_ticks_usec(); _fill(b, 453, 20); t1 = Time.get_ticks_usec()
	await _f(); print("B one layer 453 cells ysort: set_cell us ", t1 - t0, " draw calls ", _calls())
	par.free(); await _f()
	# C: 4 layers (per section 182/118/149/4) no ysort
	par = Node2D.new(); vp.add_child(par)
	var sizes := [182, 118, 149, 4]
	t0 = Time.get_ticks_usec()
	for i in 4:
		var l := TileMapLayer.new(); l.tile_set = ts; l.position = Vector2(i * 1000 % 1200, 0); par.add_child(l); _fill(l, sizes[i], 14)
	t1 = Time.get_ticks_usec()
	await _f(); print("C four section layers no-ysort: us ", t1 - t0, " draw calls ", _calls())
	par.free(); await _f()
	# D: 4 layers ysort in ysort parent
	par = Node2D.new(); par.y_sort_enabled = true; vp.add_child(par)
	t0 = Time.get_ticks_usec()
	for i in 4:
		var l := TileMapLayer.new(); l.tile_set = ts; l.y_sort_enabled = true; l.position = Vector2(i * 300, 0); par.add_child(l); _fill(l, sizes[i], 14)
	t1 = Time.get_ticks_usec()
	await _f(); print("D four section layers ysort: us ", t1 - t0, " draw calls ", _calls())
	# E: reparent cost of one ysort layer with 182 cells between two parents
	var p2 := Node2D.new(); p2.y_sort_enabled = true; vp.add_child(p2)
	var l0 := par.get_child(0)
	t0 = Time.get_ticks_usec(); l0.reparent(p2, false); t1 = Time.get_ticks_usec()
	await _f(); print("E reparent 182-cell ysort layer: us ", t1 - t0, " draw calls ", _calls())
	# F: rebuild: clear + refill 182 cells
	t0 = Time.get_ticks_usec(); l0.clear(); _fill(l0, 182, 14); t1 = Time.get_ticks_usec()
	await _f(); print("F clear+refill 182 cells ysort: us ", t1 - t0)
	# G: free whole section layer
	t0 = Time.get_ticks_usec(); l0.free(); t1 = Time.get_ticks_usec(); print("G free 182-cell layer: us ", t1 - t0)
	# H: 100 Sprite2D add/reparent
	var holder := Node2D.new(); holder.y_sort_enabled = true; vp.add_child(holder)
	var holder2 := Node2D.new(); holder2.y_sort_enabled = true; vp.add_child(holder2)
	var tex := ImageTexture.create_from_image(Image.create(48, 48, false, Image.FORMAT_RGBA8))
	var sp: Array[Sprite2D] = []
	for i in 100:
		var s := Sprite2D.new(); s.texture = tex; s.position = Vector2(i % 10 * 50, i / 10 * 50); holder.add_child(s); sp.append(s)
	await _f()
